// Distant landmarks at the side edges of the street (R1-T3, D-057; owner decision "side-edge peeks"). The silhouettes are embedded in
// arena-sky-data.js (generated by tools/gen-arena-sky.js). P.ArenaSky.draw(R, s, th, y0, y1) draws the hood's landmarks as roof-level
// elevations that scroll slower than the street (parallax K), so they read as far away. They sit under actors, telegraphs and
// overhead art, fade out on the lane side, and never cross the lane centre, so combat readability is untouched (design-system 6).
// Returns nothing; draws nothing while the images decode or when the hood has none. View only; the sim never reads this.
P.ArenaSky = (function () {
  var A = {}, IMG = {}, RASTER = {}, pending = 0;
  var K = 0.55, SPACING = 30, EDGE = 4.4, ALPHA = 0.92;

  function hash(n) { var x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); }

  function load() {
    var data = P.ArenaSkyData && P.ArenaSkyData.shapes || {};
    Object.keys(data).forEach(function (k) {
      var im = new Image();
      pending++;
      im.onload = function () { IMG[k] = im; RASTER = {}; pending--; };
      im.onerror = function () { pending--; };
      im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(data[k].svg);
    });
  }

  function raster(kind, d, k) {
    var rk = kind + '|' + k, t = RASTER[rk], cv;
    if (t) return t;
    cv = document.createElement('canvas'); cv.width = Math.ceil(d.w * k); cv.height = Math.ceil(d.h * k);
    cv.getContext('2d').drawImage(IMG[kind], 0, 0, cv.width, cv.height);
    return (RASTER[rk] = cv);
  }

  A.ready = function () { return pending === 0; };
  A.has = function (id) { return !!(P.ArenaSkyData && P.ArenaSkyData.hoods[id]); };
  A.draw = function (R, s, th, y0, y1) {
    var list = P.ArenaSkyData && P.ArenaSkyData.hoods[th.id], shapes = P.ArenaSkyData && P.ArenaSkyData.shapes, c = R.ctx, u = R.ppm, cy = R.cam.y,
      hpx = 9.5 * u, lo, hi, i, y, side, kind, d, k;
    if (!list) return;
    lo = Math.floor((cy - (R.H / 2 + hpx) / (K * u)) / SPACING); hi = Math.ceil((cy + (R.H / 2) / (K * u)) / SPACING);
    k = Math.max(1, Math.round(u * (R.dpr || 1)));
    for (i = lo; i <= hi; i++) {
      kind = list[Math.floor(hash(i * 3.1) * list.length)]; d = shapes[kind];
      if (!IMG[kind]) continue;
      side = (i % 2 ? 1 : -1) * (hash(i * 7.7) < 0.25 ? -1 : 1);
      y = i * SPACING + (hash(i * 1.9) - 0.5) * 12;
      c.save();
      c.globalAlpha = ALPHA;
      c.translate(R.X(side * EDGE), -(y - cy) * K * u);
      if (side < 0) c.scale(-1, 1);
      c.drawImage(raster(kind, d, k), -d.ax * u, -d.ay * u, d.w * u, d.h * u);
      c.restore();
    }
  };
  load();
  return A;
})();
